#!/usr/bin/env bash
set -euo pipefail
ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.."&&pwd)";EXP_ROOT="${EXP_ROOT:-/linxi/dataset/FGDD_v2/aircraft_ipc3_seed0_v1}";V1_ROOT=/linxi/dataset/FGDD_v1/aircraft_ipc3_seed0_v1;CONTROL_ROOT=/linxi/dataset/FG_SoftAugFactorial_v2/aircraft_ipc3_v1;DATA_ROOT=/linxi/dataset/FG_SRe2L_repro/v1/datasets;TRAIN_ROOT="$DATA_ROOT/A_imsize224/train";R0_IMAGES=/linxi/dataset/FG_CoDA_standard/v2/baselines/random_real_standard/selected/A_imsize224/rseed0/ipc3;R2_IMAGES="$V1_ROOT/selection/selected/r2_ordinary_gain/ipc3";R0_FKD=/linxi/dataset/FG_HardAugFactorial_v2/aircraft_ipc3_v1/fkd/fullframe_cutmix/random_real/source_seed0/ipc3_bs20_ipc3;TEACHER=/linxi/dataset/FG_SRe2L_standard/v1/teachers/A_imsize224/tseed42/ResNet18.pth;GPUS=(${GPUS:-0 1});EVALS_PER_GPU=${EVALS_PER_GPU:-4};mkdir -p "$EXP_ROOT"/{selection,logs,status,locks,fkd,results,post_eval,summary};ts(){ date --iso-8601=seconds; };images(){ [[ $1 == r2_augaware ]]&&echo "$EXP_ROOT/selection/selected/r2_augaware/ipc3"||echo "$R0_IMAGES"; };fkd(){ echo "$EXP_ROOT/fkd/$1/ipc3_bs20_ipc3"; }
prepare_selection(){ if [[ ! -f $EXP_ROOT/selection/selection_manifest.json ]];then CUDA_VISIBLE_DEVICES=0 PROTOCOL_BUFFERS_PYTHON_IMPLEMENTATION=python python -u "$ROOT_DIR/CV-DD/fine_grained/prepare_fgdd_v2_augaware.py" --train-root "$TRAIN_ROOT" --r0-root "$R0_IMAGES" --r2-root "$R2_IMAGES" --r0-fkd "$R0_FKD" --v1-root "$V1_ROOT" --teacher "$TEACHER" --output-root "$EXP_ROOT/selection" >"$EXP_ROOT/logs/selection.log" 2>&1;fi;}
prepare_fkd(){ local method gpu base actual;method=$1;gpu=$2;base="$EXP_ROOT/fkd/$method/ipc3";actual="$(fkd "$method")";if [[ $method == r2_augaware ]];then local n=0;[[ -d $actual ]]&&n=$(find "$actual" -name 'batch_*.tar' -type f|wc -l);if((n!=6000));then CUDA_VISIBLE_DEVICES=$gpu PROTOCOL_BUFFERS_PYTHON_IMPLEMENTATION=python python -u "$ROOT_DIR/CV-DD/relabel/relabel.py" --syn-data-path "$(images "$method")" --fkd-path "$base" --model-pool-dir "$(dirname "$TEACHER")" --teacher-model-name ResNet18 --gpu 0 --batch-size 20 --workers 8 --persistent-workers --dataset-name A_imsize224 --epochs 400 --seed 42 --fkd-seed 42 --full-image-resize --min-scale-crops 1 --max-scale-crops 1 --mix-type cutmix --use-fp16 --mode fkd_save >"$EXP_ROOT/logs/fkd_${method}.log" 2>&1;fi;else local graph=confusion;[[ $method == r0_random_graph_pairing ]]&&graph=randomized;if [[ ! -f $actual/pairing_manifest.json ]];then CUDA_VISIBLE_DEVICES=$gpu PROTOCOL_BUFFERS_PYTHON_IMPLEMENTATION=python python -u "$ROOT_DIR/CV-DD/fine_grained/prepare_graph_pairing_fkd.py" --images "$R0_IMAGES" --source-fkd "$R0_FKD" --destination "$actual" --selection-manifest "$V1_ROOT/selection/selection_manifest.json" --teacher "$TEACHER" --graph "$graph" >"$EXP_ROOT/logs/fkd_${method}.log" 2>&1;fi;fi;python "$ROOT_DIR/CV-DD/fine_grained/audit_fkd.py" --fkd-dir "$actual" --images 300 --classes 100 --batch-size 20 --epochs 400 --output "$actual/fkd_audit.json">>"$EXP_ROOT/logs/fkd_${method}.log" 2>&1;}
eval_one(){ local method student gpu result log;method=$1;student=$2;gpu=$3;result="$EXP_ROOT/results/$method/ipc3_sseed$student.json";log="$EXP_ROOT/logs/eval_${method}_s$student.log";mkdir -p "$(dirname "$result")";exec 7>"$result.lock";flock -n 7||return 75;if [[ ! -f $result ]];then CUDA_VISIBLE_DEVICES=$gpu PROTOCOL_BUFFERS_PYTHON_IMPLEMENTATION=python OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 MKL_NUM_THREADS=1 python -u "$ROOT_DIR/CV-DD/validate/train_fkd.py" --model ResNet18 --ipc 3 --exp-name "fgdd_v2_${method}_s$student" --original-data-path "$(images "$method")" --fkd-path "$(fkd "$method")" --output-dir "$EXP_ROOT/post_eval/$method/sseed$student" --batch-size 20 --epochs 400 --dataset-name A_imsize224 --gradient-accumulation-steps 2 --mix-type cutmix --workers 8 --persistent-workers --fkd_seed 42 --train-seed "$student" --temperature 20 --student-initialization imagenet-v1 --student-protocol-name standard_protocol_v2_fgdd_v2 --adamw-weight-decay 1e-5 --adamw-beta1 .9 --adamw-beta2 .999 --adamw-eps 1e-8 --adamw-backbone-lr 1e-4 --adamw-head-lr 1e-3 --cosine-t-max 400 --cosine-eta-min 0 --val-dir "$DATA_ROOT/A_imsize224/test" --disable-wandb --per-class-output "$result">"$log" 2>&1;fi;}
main(){ exec 9>"$EXP_ROOT/locks/launcher.lock";flock -n 9||exit 75;rm -f "$EXP_ROOT/status/launcher.failed" "$EXP_ROOT/status/launcher.complete";echo "$(ts) started new_fkd=3 new_students=9">"$EXP_ROOT/status/launcher.running";prepare_selection;echo "$(ts) complete">"$EXP_ROOT/status/selection.complete";local pids=() i=0 method gpu p failed=0;for method in r2_augaware r0_confusion_pairing r0_random_graph_pairing;do gpu=${GPUS[$((i%2))]};prepare_fkd "$method" "$gpu"&pids+=("$!");i=$((i+1));if((${#pids[@]}==2));then for p in "${pids[@]}";do wait "$p"||failed=1;done;((failed==0));pids=();fi;done;for p in "${pids[@]}";do wait "$p"||failed=1;done;((failed==0));echo "$(ts) complete">"$EXP_ROOT/status/fkd.complete";pids=();i=0;local student;for method in r2_augaware r0_confusion_pairing r0_random_graph_pairing;do for student in 42 43 44;do gpu=${GPUS[$((i%2))]};eval_one "$method" "$student" "$gpu"&pids+=("$!");i=$((i+1));if((${#pids[@]}==2*EVALS_PER_GPU));then for p in "${pids[@]}";do wait "$p"||failed=1;done;((failed==0));pids=();fi;done;done;for p in "${pids[@]}";do wait "$p"||failed=1;done;((failed==0));python "$ROOT_DIR/CV-DD/fine_grained/summarize_fgdd_v2_aircraft.py" --root "$EXP_ROOT" --v1-root "$V1_ROOT" --control-root "$CONTROL_ROOT">"$EXP_ROOT/logs/summary.log" 2>&1;rm -f "$EXP_ROOT/status/launcher.running";echo "$(ts) complete">"$EXP_ROOT/status/launcher.complete";}
trap 'r=$?;if((r));then rm -f "$EXP_ROOT/status/launcher.running";echo "$(ts) exit=$r">"$EXP_ROOT/status/launcher.failed";fi' EXIT
main
